/**
 * memory-store — 跨会话用户记忆的 BFF 权威存储（P2 长期记忆）。
 *
 * ## 为什么存 BFF 而不是 迁移前的 usePersistentState
 *
 * `usePersistentState` 按会话隔离，新会话读不到旧会话写入——偏好当年为此
 * 被迫做了"agent 内存状态 + BFF 副本"双写。记忆从一开始就只存 BFF 一份
 * （data/memory.json），agent 经 remember 工具写、环境块读，天然跨会话，
 * 没有双写漂移问题。
 *
 * ## 形态
 *
 * 单用户场景刻意不做向量/RAG：条目是用户亲口说过的短句（≤200 字），
 * 注入按 lastSeenAt + hits 取 top N 进环境块「记忆：」行。上限 50 条，
 * 超出按 lastSeenAt 最旧淘汰（刚写入的绝不淘汰）。
 *
 * 并发：与 preferences-store 同款简化权衡——单用户低频写，读-改-整写
 * 不加锁；最坏丢一次并发写，可接受。
 */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

export type MemoryKind = 'fact' | 'routine' | 'event';

export type MemoryEntry = {
	id: string;
	/** 用户原话或其紧凑转写（≤200 字） */
	text: string;
	kind: MemoryKind;
	createdAt: string;
	/** 去重命中时刷新，作为"还在用"的信号 */
	lastSeenAt: string;
	hits: number;
};

const MEMORY_PATH = resolve('data/memory.json');
const MAX_MEMORIES = 50;
const MAX_TEXT = 200;

/** 归一化用于去重：去首尾、压空白。中文不做更激进的归一化（误伤率高于收益）。 */
function normalize(text: string): string {
	return text.trim().replace(/\s+/g, ' ');
}

function truncate(text: string, max: number): string {
	return text.length > max ? `${text.slice(0, max)}…` : text;
}

/** 读取全部记忆。文件不存在/损坏时返回空数组（记忆是增强，绝不阻塞主链路）。 */
export async function readMemories(): Promise<MemoryEntry[]> {
	try {
		const parsed = JSON.parse(await readFile(MEMORY_PATH, 'utf8')) as unknown;
		if (!Array.isArray(parsed)) return [];
		return parsed.filter(
			(m): m is MemoryEntry =>
				!!m && typeof (m as MemoryEntry).id === 'string' && typeof (m as MemoryEntry).text === 'string',
		);
	} catch {
		return [];
	}
}

/**
 * 环境块注入用：取最"活"的 n 条（最近见过优先，同近度看命中次数）。
 */
export async function topMemories(n: number): Promise<MemoryEntry[]> {
	return [...(await readMemories())]
		.sort((a, b) => b.lastSeenAt.localeCompare(a.lastSeenAt) || b.hits - a.hits)
		.slice(0, Math.max(0, n));
}

/**
 * 记一条。归一化后命中已有条目则刷新 lastSeenAt/hits（并按需更新 kind），
 * 否则新建。返回最终条目与当前总数。
 */
export async function rememberFact(
	rawText: string,
	kind?: MemoryKind,
): Promise<{ memory: MemoryEntry; total: number }> {
	const text = truncate(normalize(rawText), MAX_TEXT);
	const now = new Date().toISOString();
	const all = await readMemories();

	const existing = all.find((m) => normalize(m.text) === text);
	let memory: MemoryEntry;
	if (existing) {
		existing.lastSeenAt = now;
		existing.hits += 1;
		if (kind) existing.kind = kind;
		memory = existing;
	} else {
		memory = {
			id: `mem-${Math.random().toString(36).slice(2, 10)}`,
			text,
			kind: kind ?? 'fact',
			createdAt: now,
			lastSeenAt: now,
			hits: 1,
		};
		all.push(memory);
	}

	// 容量淘汰：超限时按 lastSeenAt 最旧删除（memory 刚建/刚命中，必不在淘汰集）
	if (all.length > MAX_MEMORIES) {
		const keep = new Set(
			[...all]
				.sort((a, b) => b.lastSeenAt.localeCompare(a.lastSeenAt))
				.slice(0, MAX_MEMORIES)
				.map((m) => m.id),
		);
		keep.add(memory.id);
		for (let i = all.length - 1; i >= 0; i--) {
			if (!keep.has(all[i]!.id)) all.splice(i, 1);
		}
	}

	await persist(all);
	return { memory, total: all.length };
}

/** 删除单条（id 不存在返回 false）。 */
export async function deleteMemory(id: string): Promise<boolean> {
	const all = await readMemories();
	const next = all.filter((m) => m.id !== id);
	if (next.length === all.length) return false;
	await persist(next);
	return true;
}

/** 清空全部。 */
export async function clearMemories(): Promise<number> {
	const n = (await readMemories()).length;
	await persist([]);
	return n;
}

async function persist(entries: MemoryEntry[]): Promise<void> {
	await mkdir(dirname(MEMORY_PATH), { recursive: true });
	await writeFile(MEMORY_PATH, JSON.stringify(entries, null, 2), 'utf8');
}
