/**
 * Memory route — 跨会话用户记忆 CRUD（P2 长期记忆）。
 *
 * - GET    /api/memory          列出全部记忆（按 lastSeenAt 降序）
 * - POST   /api/memory          记一条（agent 的 remember 工具调用；归一化去重）
 * - DELETE /api/memory?id=x     删单条；不带 id 清空
 *
 * 权威源就是本路由操作的 data/memory.json（与偏好不同，无第二处副本，
 * 见 server/user/memory-store.ts 头注）。前端不做记忆 UI（视觉冻结约束）。
 */
import {
	clearMemories,
	deleteMemory,
	readMemories,
	rememberFact,
	type MemoryKind,
} from '@/server/user/memory-store';
import { ok, fail } from '@/server/http';

const KINDS = new Set(['fact', 'routine', 'event']);

export async function GET() {
	const items = (await readMemories()).sort((a, b) => b.lastSeenAt.localeCompare(a.lastSeenAt));
	return ok({ items, total: items.length });
}

export async function POST(request: Request) {
	let body: { text?: unknown; kind?: unknown };
	try {
		body = (await request.json()) as { text?: unknown; kind?: unknown };
	} catch {
		return fail('Invalid JSON body', 400);
	}
	if (typeof body.text !== 'string' || !body.text.trim()) {
		return fail('text 不能为空', 400);
	}
	const kind =
		typeof body.kind === 'string' && KINDS.has(body.kind) ? (body.kind as MemoryKind) : undefined;
	const { memory, total } = await rememberFact(body.text, kind);
	return ok({ memory, total });
}

export async function DELETE(request: Request) {
	const id = new URL(request.url).searchParams.get('id');
	if (id) {
		const removed = await deleteMemory(id);
		if (!removed) {
			return fail(`记忆不存在：${id}`, 404);
		}
		return ok({ removed: id });
	}
	const cleared = await clearMemories();
	return ok({ cleared });
}
